[797]="反攻魔界之时已到\n请祖师<color=#ca631d>点击此处</color>\n号令宗门弟子集结！",
[798]="仙军列阵整装待发\n请祖师<color=#ca631d>点击</color>破开魔界",
[799]="请祖师<color=#ca631d>点击此处</color>\n选择要加入的势力",
[800]="玉京、蓬莱和九渊\n皆对祖师有招揽之意",
[801]="三大势力各有所长\n对祖师必大有裨益",
[802]="譬如九渊擅长征伐\n攻之必克锐不可当",
[803]="玉京擅长禁制困敌\n以此削弱敌人实力",
[804]="蓬莱有仙灵助力\n请祖师自行查看",
[805]="待祖师选定心仪势力\n点击此处加入势力吧",
[806]="请祖师<color=#ca631d>斩妖除魔</color>\n为大军扫清障碍",
[807]="请祖师<color=#ca631d>摧城破宗</color>\n为大军扫清障碍",
[808]="尊侯赐下的宝鼎，\n专为我军<color=#ca631d>炼制辎重</color>所备",
[809]="仙友可将这些<color=#ca631d>魔魂</color>\n投入此鼎中。",
[810]="请诸位祖师勠力同心\n攻伐魔将，成无上伟业",
[811]="每位魔将\n持有法则各不相同\n祖师可按需调配弟子",
[812]="每日指定时间内\n可攻打魔将\n请祖师谨记时间",
[813]="若是当日未将其击败\n则次日魔将血量回满",
[814]="魔将阶数会随时间变化\n请祖师<color=#ca631d>点击此处</color>查看",
[815]="魔将次日阶数会减一\n魔将阶数越低\n则魔将实力越弱",
[816]="魔将状态\n会随时间流逝变化\n请祖师<color=#ca631d>点击此处</color>查看",
[817]="越早击败魔将\n祖师获取的奖励\n也会越加丰厚",
[818]="请祖师<color=#ca631d>击败魔将</color>\n为大军破开关隘",
[819]="九渊恭迎祖师加入\n我待此日已久了",
[820]="若祖师望重选势力\n可在此进行重选",
[821]="平日有不少事务\n祖师可在此处理",
[822]="九渊善长攻伐之法\n请祖师<color=#ca631d>点击此处</color>查看",
[823]="九渊仙法可在此升级\n使其发挥更大功效",
[824]="请祖师<color=#ca631d>点击此处</color>\n了解仙法如何使用",
[825]="欢迎祖师加入蓬莱\n来与大家一起逍遥",
[826]="蓬莱平日事务\n可在此查看",
[827]="蓬莱擅长护佑之法\n请祖师<color=#ca631d>点击此处</color>查看",
[828]="蓬莱仙法可在此升级\n使其发挥更大功效",
[829]="恭迎祖师尊驾\n玉京待祖师已久",
[830]="玉京平日事务\n请祖师在此处理",
[831]="玉京善长禁制之法\n请祖师<color=#ca631d>点击此处</color>查看",
[832]="玉京仙法可在此升级\n使其发挥更大功效",
[833]="此战既是最后一战\n请祖师攻打魔君\n光复此域",
[834]="魔君暴虐无比\n每隔半时辰便袭击仙军\n请祖师<color=#ca631d>点击此处</color>查看。",
[835]="每当魔君亏损一定气血\n便会随机触发一种效果\n请祖师留意",
[836]="劳烦祖师\n<color=#ca631d>点击此处</color>返回",
[837]="魔君诡变多端\n请祖师留意",
[838]="规则详细悉载于此\n祖师可<color=#ca631d>点击此处</color>查看",
[839]="请祖师<color=#ca631d>攻打关口</color>\n为仙军开境扫清障碍",
[840]="魔宫护卫将择时现身\n请祖师<color=#ca631d>击败魔宫护卫</color>\n为大军清扫障碍",
[841]="魔宗已被悉数清空\n请祖师备战魔将",
[842]="云舟阵图有诸多<color=#ca631d>阵枢</color>\n各有功效",
[843]="请祖师点击查看<color=#ca631d>阵枢</color>",
[844]="激活枢纽\n会获得属性增益",
[845]="特殊效果只对\n云舟出征的弟子生效",
[846]="阵枢激活条件各不相同\n请祖师在此处查看",
[847]="冥渊之地十分凶险\n请留意弟子状态",
[848]="每次击败怪物\n队伍弟子会减少<color=#ca631d>灵力</color>",
[849]="灵力越低，弟子战力\n也会随之降低",
[850]="击败怪物会获得煞晶\n可在冥渊商人处，恢复弟子<color=#ca631d>灵力</color>",
[851]="请祖师返回冥渊",
[852]="弟子总战力达到条件\n可以直接斩灭怪物",
[853]="斩妖需消耗弟子<color=#ca631d>灵力</color>\n还请祖师合理布阵",
[854]="请诸位随我来吧",
[855]="此处就是灵兽峰了",
[856]="此为本源阵基\n请祖师击溃此物\n破除邪阵",
[857]="本源阵基魔气强盛\n需先废除五行阵基\n破除魔气方可攻打",
[858]="请祖师<color=#ca631d>点击此处</color>\n返回魔域",
[859]="请祖师<color=#ca631d>点击此处</color>\n随我前来",
[860]="请祖师<color=#ca631d>点击此处</color>\n搜寻五行阵基",
[861]="祖师可于此处\n前往五行阵基",
[862]="请祖师<color=#ca631d>破除阵眼</color>\n为大军扫清障碍",
[863]="请祖师<color=#ca631d>摧毁阵基</color>\n为仙军扫清障碍",
[864]="请祖师<color=#ca631d>点击此处</color>\n搜寻本源阵基",
[865]="祖师可于此处\n搜寻本源阵基",
[866]="请祖师<color=#ca631d>点击此处</color>\n随我搜寻关口",
[867]="请祖师与仙盟商议\n选择攻打的关口吧",
[868]="喵~一起去看看\n灵兽的情况吧",
[869]="灵兽的资质特性\n各不相同，有千般模样",
[870]="让我们去提升一次\n灵兽的境界",
[871]="赠你几枚饲灵丸\n喂给它吃吧,喵~",
[872]="血脉乃是灵兽根基\n凝练血脉至关重要",
[873]="灵兽需修为足够\n方可凝练血脉",
[874]="灵兽系统开启了\n一起去看看喵",
[875]="此域妖兽肆掠\n还需祖师相助。",
[876]="一只失控的灵兽\n抓住它，喵！",
[877]="抓住它，喵！",
[878]="灵苑尚存，久未饲兽",
[879]="此灵苑残破\n还需修缮一番",
[880]="灵苑已修缮完毕",
[881]="请仙友入内一观",
[882]="兽栏容积决定可\n饲养的灵兽数量",
[883]="不同灵兽对生长环境的需求各异",
[884]="请仙友移步",
[885]="安排弟子照料灵兽\n可助其修为精进。",
[886]="安排一名弟子",
[887]="灵兽现可入住育灵苑了",
[888]="安放一只灵兽",
[889]="兽栏初立根基已固，苑内灵兽成长加速",
[890]="抓到新灵兽了\n让我们一起去看看",
[891]="灵兽在这里，喵~",
[892]="让灵兽与弟子协同作战",
[893]="灵兽能够为弟子提供助益，带来战力加成",
[894]="灵兽能够为弟子提供助益，带来战斗加成",
[895]="弟子的饲养属性越高，灵兽提供的战力越高",
[896]="灵宠藏匿于草丛中\n祖师可翻草丛捕获~",
[897]="翻草丛可寻得更多葫芦\n也可提升葫芦品质",
[898]="捉妖葫的数量与品质\n会决定灵宠数量品质",
[899]="请祖师回去看看~",
[900]="请祖师找到\n藏匿的灵宠吧~",
[901]="可以繁衍灵兽啦，请祖师先安排弟子",
[902]="弟子饲养等级越高，灵兽成长耗时就会越短",
[903]="有了弟子之后就可以选择灵兽啦",
[904]="想要灵兽进行繁衍也需要特定条件",
[905]="灵兽可以在兽栏里恢复心情值",
[906]="要繁衍出更好的灵兽还需要关注一些其它事项",
[907]="灵兽繁衍的秘诀全都在这里啦~",
[908]="现在向着培育出更强的灵兽前进吧！",
[909]="点击开始小游戏！",
